SELECT SUBSTRING(referer FROM POSITION('://' IN referer) + 3 FOR CASE WHEN POSITION('/' IN SUBSTRING(referer FROM POSITION('://' IN referer) + 3)) > 0 THEN POSITION('/' IN SUBSTRING(referer FROM POSITION('://' IN referer) + 3)) - 1 ELSE CHAR_LENGTH(referer) END) AS k, AVG(CHAR_LENGTH(referer)) AS l, COUNT(*) AS c, MIN(referer) FROM hits WHERE referer <> '' GROUP BY SUBSTRING(referer FROM POSITION('://' IN referer) + 3 FOR CASE WHEN POSITION('/' IN SUBSTRING(referer FROM POSITION('://' IN referer) + 3)) > 0 THEN POSITION('/' IN SUBSTRING(referer FROM POSITION('://' IN referer) + 3)) - 1 ELSE CHAR_LENGTH(referer) END) HAVING COUNT(*) > 100000 ORDER BY l DESC LIMIT 25;
